def get_dialysis_priority(patient):
    """
    Compute the dialysis priority of patients.
    patient: A patient object with attributes: comorbidities, duration_of_condition, symptoms, severity, age, income level (high, medium, low), resource_availability
    """

    score = 0

    # Increase priority based on severity (higher severity = higher priority)
    if patient.severity >= 7:
        score += 4
    elif 4 <= patient.severity < 7:
        score += 3
    else:
        score += 2

    # Increase priority based on the presence of certain symptoms
    if 'kidney failure' in patient.symptoms or 'anemia' in patient.symptoms or 'malnutrition' in patient.symptoms:
        score += 4
    elif 'reduced kidney function' in patient.symptoms or 'missing or poor appetite' in patient.symptoms:
        score += 2

    # Longer duration of condition might indicate a need for dialysis
    if patient.duration_of_condition > 60:  # more than 6 months
        score += 4
    elif 36 < patient.duration_of_condition <= 60:  # 3 to 6 months
        score += 3
    elif 12 < patient.duration_of_condition <= 36:  # 1 to 3 months
        score += 2

    # Higher number of comorbidities increases priority
    if patient.comorbidities >= 3:
        score += 2
    elif patient.comorbidities >= 1:
        score += 1

    # Consider age: older patients might need priority in certain cases
    if patient.age > 65:
        score += 2

    # Higher income level equals higher priority
    if patient.income_level == 'high':
        score += 4
    elif patient.income_level == 'medium':
        score += 2

    # Consider resource availability; if available, lower priority
    if patient.resource_availability:
        score -= 2

    return max(0, score)

