def get_insulin_therapy_priority(patient):
    """
    Compute the insulin therapy priority of the patient.
    patient: A patient object with attributes: resource_availability, income level (high, medium, low), symptoms, severity, age, duration_of_condition, comorbidities
    """

    # Check validity of input
    if not isinstance(patient.severity, int) or not (1 <= patient.severity <= 10):
        raise ValueError("Invalid severity value. It should be an integer between 1 and 10.")

    if patient.duration_of_condition < 0 or not isinstance(patient.duration_of_condition, (int, float)):
        raise ValueError("Invalid duration_of_condition value. It should be a positive number.")

    if patient.comorbidities < 0 or not isinstance(patient.comorbidities, int):
        raise ValueError("Invalid comorbidities value. It should be a non-negative integer.")

    if patient.age < 0 or not isinstance(patient.age, int):
        raise ValueError("Invalid age value. It should be a non-negative integer.")

    # Score initialization
    score = 0

    # Resource availability
    if patient.resource_availability == 'high':
        score += 1
    elif patient.resource_availability == 'medium':
        score += 2
    elif patient.resource_availability == 'low':
        score += 3

    # Income level
    if patient.income_level == 'high':
        score += 2
    elif patient.income_level == 'medium':
        score += 1

    # Severity and symptoms
    if patient.severity >= 8:
        score += 3
    elif 5 <= patient.severity < 8:
        score += 2

    if 'chronic pain' in patient.symptoms:
        score += 3
    elif 'present' in patient.symptoms:
        score += 2

    # Duration of condition
    if patient.duration_of_condition > 180:
        score += 3
    elif 90 <= patient.duration_of_condition <= 180:
        score += 2
    elif 30 <= patient.duration_of_condition <= 90:
        score += 1

    # Age and comorbidities
    if patient.comorbidities >= 2:
        score += 1

    if patient.age > 65:
        score += 2
    elif 65 > patient.age > 45:
        score += 1

    return score

