    if any(symptom in patient.symptoms for symptom in serious_symptoms):
        score += 3
    elif 'seizures' in patient.symptoms:
        score += 2
    elif any(symptom in patient.symptoms for symptom in ['low energy', 'high cholesterol']):
        score += 1

