def get_group_therapy_priority(patients):
    """
    Compute the group therapy priority of the patient.
    patients: A list of patient objects with attributes: income level (high, medium, low), resource_availability, age, duration_of_condition, severity, comorbidities, symptoms
    """
    priority_scores = []

    for patient in patients:
        score = 0

        # Increase priority based on income level (higher income = higher priority)
        if patient.income_level == 'high':
            score += 3
        elif patient.income_level == 'medium':
            score += 2
        else:
            score += 1

        # Increase priority based on the presence of debilitating symptoms
        # Assume we have a dictionary of prevalent symptoms in the group
        prevalent_symptoms = {}
        for patient in patients:
            for symptom in patient.symptoms:
                if symptom not in prevalent_symptoms:
                    prevalent_symptoms[symptom] = 1
                else:
                    prevalent_symptoms[symptom] += 1

        # Assign higher scores to patients with prevalent symptoms
        for symptom, count in prevalent_symptoms.items():
            if count > len(patients) / 2:  # More than half of the group has this symptom
                if 'chronic pain' in symptom:
                    score += 3
                elif 'reduced mobility' in symptom or 'ongoing fatigue' in symptom:
                    score += 2

        # Consider age: middle-aged or older patients might need priority in certain cases
        if 45 <= patient.age <= 65:
            score += 2
        elif patient.age > 65:
            score += 1

        priority_scores.append(score)

    # Calculate the average score across the group
    avg_score = sum(priority_scores) / len(priority_scores)

    return avg_score

