def get_family_therapy_priority(patient):
    """
    Compute the family therapy priority of the patient.
    patient: A patient object with attributes: duration_of_condition, income level (high, medium, low), symptoms, 
             comorbidities, age, severity, resource_availability
    """
    score = 0

    # Higher duration of condition increases priority
    if patient.duration_of_condition > 24:  # more than 6 months
        score += 3
    elif 12 < patient.duration_of_condition <= 24:  # 3 to 6 months
        score += 2
    elif 4 < patient.duration_of_condition <= 12:  # 1 to 3 months
        score += 1

    # Patient's income level indicates resource availability
    if patient.income_level == 'high':
        score += 2
    elif patient.income_level == 'medium':
        score += 1

    # Significant impact of debilitating symptoms
    if 'chronic pain' in patient.symptoms or 'reduced mobility' in patient.symptoms or 'ongoing fatigue' in patient.symptoms:
        score += 3
    elif 'reduced mobility' in patient.symptoms or 'ongoing fatigue' in patient.symptoms:
        score += 2
    else:
        score += 1

    # Higher number of comorbidities increases priority
    if patient.comorbidities >= 3:
        score += 2
    elif patient.comorbidities >= 1:
        score += 1

    # Age should also be considered, older patients may require more support
    if patient.age > 65:
        score += 2
    elif patient.age > 45:
        score += 1

    # Severity can have direct impact on symptoms
    if patient.severity >= 7:
        score += 3
    elif patient.severity >= 4:
        score += 2
    else:
        score += 1

    # Resource availability might affect priority to some extent
    if patient.resource_availability <= 2:
        score -= 2
    elif patient.resource_availability == 1:
        score -= 1

    return max(score, 0)  # ensure non-negative score

