def isHappy(n):
    slow = n
    fast = get_next(n)
    while fast != 1 and fast != slow:
        slow = get_next(slow)
        fast = get_next(get_next(fast))
    return fast == 1

def get_next(n):
    total_sum = 0
    while n > 0:
        n, digit = divmod(n, 10)
        total_sum += digit ** 2
    return total_sum

